mkuse!{use super :: { MIN_ALIGN , realloc_fallback } ;}
mkuse!{use crate :: alloc :: { GlobalAlloc , Layout , System } ;}
mkuse!{use crate :: ptr ;}
mkitem!{mkimpl!{# [stable (feature = "alloc_system_type" , since = "1.28.0")] unsafe impl GlobalAlloc for System { # [inline] unsafe fn alloc (& self , layout : Layout) -> * mut u8 { if layout . align () <= MIN_ALIGN && layout . align () <= layout . size () { unsafe { libc :: malloc (layout . size ()) as * mut u8 } } else { # [cfg (target_vendor = "apple")] { if layout . align () > (1 << 31) { return ptr :: null_mut () ; } } unsafe { aligned_malloc (& layout) } } } # [inline] unsafe fn alloc_zeroed (& self , layout : Layout) -> * mut u8 { if layout . align () <= MIN_ALIGN && layout . align () <= layout . size () { unsafe { libc :: calloc (layout . size () , 1) as * mut u8 } } else { let ptr = unsafe { self . alloc (layout) } ; if ! ptr . is_null () { unsafe { ptr :: write_bytes (ptr , 0 , layout . size ()) } ; } ptr } } # [inline] unsafe fn dealloc (& self , ptr : * mut u8 , _layout : Layout) { unsafe { libc :: free (ptr as * mut libc :: c_void) } } # [inline] unsafe fn realloc (& self , ptr : * mut u8 , layout : Layout , new_size : usize) -> * mut u8 { if layout . align () <= MIN_ALIGN && layout . align () <= new_size { unsafe { libc :: realloc (ptr as * mut libc :: c_void , new_size) as * mut u8 } } else { unsafe { realloc_fallback (self , ptr , layout , new_size) } } } }}}
